function rumorFor(t,w){const a=['has a suspiciously strong opinion about airport carpet','refuses to rank breakfast foods before noon','believes every road trip needs one unnecessary gas-station purchase','keeps a mental ranking of grocery-store parking lots','claims the best game-day snack is whichever one requires the least cleanup','has been researching a hobby they are absolutely not ready to admit is becoming serious','judges restaurants partly by the quality of their ice','would rather reorganize a closet than watch a preseason recap'];let h=0;for(const ch of String(t.manager_name||t.roster_id)+String(w))h=(h*31+ch.charCodeAt(0))>>>0;return a[h%a.length]}
