 for(const [id,p] of Object.entries(players)){const name=String(p?.full_name||[p?.first_name,p?.last_name].filter(Boolean).join(' ')||'').trim();if(name.length<4)continue;counts.set(name,(counts.get(name)||0)+1);ids.set(name,String(id))}
