async function loadArchivedEdition(year,week,team='',scrollMode='article'){
 const y=Number(year),w=Number(week);if(!y||!w)return;
 const r=await fetch('/.netlify/functions/league-hub?broadcast_season='+y+'&broadcast_week='+w,{cache:'no-store'}),x=await r.json();
 weeklyCache=x;
 const desired=String(team||openBroadcastTeam||'__league__'),exists=desired==='__league__'||(x?.teams||[]).some(t=>String(t.roster_id)===desired);
 openBroadcastTeam=exists?desired:(x?.league_overview?'__league__':String(x?.teams?.[0]?.roster_id||''));
 showWeeklyArticle(x,true,scrollMode);
}
function scrollToInquirerTop(){requestAnimationFrame(()=>window.scrollTo({top:0,behavior:'auto'}))}
function scrollToInquirerArticle(){requestAnimationFrame(()=>{const target=document.querySelector('#leagueHub .lh-report .lh-article-picker')||document.querySelector('#leagueHub .lh-report');if(!target)return;const top=Math.max(0,window.scrollY+target.getBoundingClientRect().top-110);window.scrollTo({top,behavior:'auto'})})}
